      await announce({phase:'downloading',attempt,bytes:0,completed:0,
        message:attempt===1?'正在下载离线应用…':`网络中断，正在第 ${attempt} 次下载离线应用…`});
      const response=await fetch(new Request(PACK_URL,{cache:'no-store',credentials:'omit',mode:'same-origin',
        redirect:'error',referrerPolicy:'no-referrer',signal:controller.signal}));
